import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"功能接入总表","description":"","frontmatter":{},"headers":[],"relativePath":"features/matrix.md","filePath":"features/matrix.md","lastUpdated":null}'),r={name:"features/matrix.md"};function h(c,t,l,s,n,i){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="功能接入总表" tabindex="-1">功能接入总表 <a class="header-anchor" href="#功能接入总表" aria-label="Permalink to &quot;功能接入总表&quot;">​</a></h1><p>本篇是<strong>权威对照表</strong>。手写 <code>mod.json</code> 时，参数键名和取值范围<strong>以本页为准</strong>。</p><div class="tip custom-block"><p class="custom-block-title">怎么读这张表</p><table tabindex="0"><thead><tr><th>列</th><th>含义</th></tr></thead><tbody><tr><td><strong>参数键</strong></td><td>写在 mod.json 里的名字</td></tr><tr><td><strong>默认</strong></td><td>「原版值」。框架认为的正常值</td></tr><tr><td><strong>滑块范围</strong></td><td>面板上拖动能到的范围（推荐日常使用）</td></tr><tr><td><strong>硬边界</strong></td><td>框架接受的绝对范围。<strong>超出会被静默截断</strong></td></tr><tr><td><strong>说明</strong></td><td>这个参数干什么</td></tr></tbody></table></div><h2 id="战斗类" tabindex="-1">战斗类 <a class="header-anchor" href="#战斗类" aria-label="Permalink to &quot;战斗类&quot;">​</a></h2><h3 id="主炮" tabindex="-1">主炮 <a class="header-anchor" href="#主炮" aria-label="Permalink to &quot;主炮&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>gun.damageMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>主炮伤害倍率</td></tr><tr><td><code>gun.accuracyMul</code></td><td>1.0</td><td>0.5 – 1.5</td><td>0 – 3</td><td>主炮射击后精准度倍率</td></tr><tr><td><code>gun.spreadMul</code></td><td>1.0</td><td>0.5 – 1.5</td><td>0 – 3</td><td>主炮散布倍率</td></tr></tbody></table><h3 id="鱼雷" tabindex="-1">鱼雷 <a class="header-anchor" href="#鱼雷" aria-label="Permalink to &quot;鱼雷&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>torpedo.damageMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>鱼雷伤害倍率</td></tr><tr><td><code>torpedo.accuracyMul</code></td><td>1.0</td><td>0.5 – 1.5</td><td>0 – 2</td><td>鱼雷命中率倍率</td></tr><tr><td><code>torpedo.turnMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 3</td><td>鱼雷转向灵活度倍率（<strong>双方对等</strong>）</td></tr></tbody></table><h3 id="航弹" tabindex="-1">航弹 <a class="header-anchor" href="#航弹" aria-label="Permalink to &quot;航弹&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>bomb.damageMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>航弹伤害倍率</td></tr><tr><td><code>bomb.accuracyMul</code></td><td>1.0</td><td>0.5 – 1.5</td><td>0 – 2</td><td>航弹命中率倍率</td></tr></tbody></table><h3 id="反潜武器" tabindex="-1">反潜武器 <a class="header-anchor" href="#反潜武器" aria-label="Permalink to &quot;反潜武器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>dc.damageMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>深水炸弹伤害倍率</td></tr><tr><td><code>hedgehog.damageMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>刺猬弹伤害倍率</td></tr></tbody></table><h2 id="环境类" tabindex="-1">环境类 <a class="header-anchor" href="#环境类" aria-label="Permalink to &quot;环境类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>wind.shellsMul</code></td><td>1.0</td><td>0.0 – 3.0</td><td>0 – 5</td><td>风向对炮弹的影响强度倍率</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title"><code>wind.shellsMul</code> 可以调到 0</p><p>调到 <code>0</code> = 完全无风偏影响，弹道更稳定。</p></div><h2 id="感知类" tabindex="-1">感知类 <a class="header-anchor" href="#感知类" aria-label="Permalink to &quot;感知类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>sensor.sonarRangeMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>声呐探测距离倍率（<strong>双方对等</strong>）</td></tr><tr><td><code>sensor.radarRangeMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>雷达探测距离倍率（<strong>双方对等</strong>）</td></tr></tbody></table><h2 id="航空类" tabindex="-1">航空类 <a class="header-anchor" href="#航空类" aria-label="Permalink to &quot;航空类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>air.wingSizeMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 4</td><td>舰载机联队规模倍率</td></tr></tbody></table><h2 id="经济类" tabindex="-1">经济类 <a class="header-anchor" href="#经济类" aria-label="Permalink to &quot;经济类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>economy.renownGainMul</code></td><td>1.0</td><td>0.5 – 5.0</td><td>0 – 100</td><td>威望获取倍率</td></tr><tr><td><code>repair.timeMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>舰船修理时间倍率（0 = 立即修好）</td></tr></tbody></table><h2 id="ai-类" tabindex="-1">AI 类 <a class="header-anchor" href="#ai-类" aria-label="Permalink to &quot;AI 类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>ai.reactionMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 3</td><td>AI 反应速度倍率（难度）</td></tr></tbody></table><h2 id="沙盒与调试类" tabindex="-1">沙盒与调试类 <a class="header-anchor" href="#沙盒与调试类" aria-label="Permalink to &quot;沙盒与调试类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>滑块范围</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>sandbox.timeScale</code></td><td>1.0</td><td>0.0 – 3.0</td><td>0 – 5</td><td>游戏时间缩放（0 = 暂停，1 = 原版）</td></tr><tr><td><code>sandbox.instantRepair</code></td><td>0</td><td>0 – 1</td><td>0 – 1</td><td>玩家舰船立即修好（0/1）</td></tr><tr><td><code>sandbox.startRenown</code></td><td>0</td><td>0 – 100</td><td>0 – 500</td><td>新战役额外起始威望（<strong>千</strong>）</td></tr><tr><td><code>unlock.allShips</code></td><td>0</td><td>0 – 1</td><td>0 – 1</td><td>沙盒解锁全部内置舰级（0/1）</td></tr><tr><td><code>local.versus</code></td><td>0</td><td>0 – 1</td><td>0 – 1</td><td>本地双人热座（关 AI）（0/1）</td></tr><tr><td><code>debug.verbose</code></td><td>0</td><td>0 – 1</td><td>0 – 1</td><td>调试日志开关（0/1）</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">硬边界是静默的</p><p>如果你手写 <code>gun.damageMul: 99</code>，而硬边界是 <code>5</code>，框架<strong>不报错</strong>，直接当成 <code>5</code>。</p><p><strong>这会造成「我明明写了 99 却没效果」的困惑。</strong> 所以：</p><ul><li><strong>面板拖滑块</strong> → 永远在范围内，不会遇到这问题</li><li><strong>手写 mod.json</strong> → 对照本表的「硬边界」列</li></ul></div><h2 id="双方对等的参数" tabindex="-1">双方对等的参数 <a class="header-anchor" href="#双方对等的参数" aria-label="Permalink to &quot;双方对等的参数&quot;">​</a></h2><p>标了「<strong>双方对等</strong>」的参数，调高后<strong>敌人也一起受益</strong>：</p><table tabindex="0"><thead><tr><th>参数</th><th>为什么对等</th></tr></thead><tbody><tr><td><code>torpedo.turnMul</code></td><td>鱼雷的物理特性对双方一样</td></tr><tr><td><code>sensor.sonarRangeMul</code></td><td>声呐是硬件能力，敌方也有</td></tr><tr><td><code>sensor.radarRangeMul</code></td><td>同上</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">想要单方面优势</p><p>调<strong>伤害</strong>或<strong>命中</strong>类参数 —— 那些只影响你的武器表现。</p><p>或者用<strong>环境类</strong>参数（如 <code>wind.shellsMul</code> 调低），那是改变整个战场的规则。</p></div><h2 id="保留字-写在-mod-json-里必须用英文原值" tabindex="-1">保留字（写在 mod.json 里必须用英文原值） <a class="header-anchor" href="#保留字-写在-mod-json-里必须用英文原值" aria-label="Permalink to &quot;保留字（写在 mod.json 里必须用英文原值）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>可用值</th></tr></thead><tbody><tr><td><code>timeOfDay</code></td><td><code>Noon</code> / <code>Dawn</code> / <code>Dusk</code> / <code>Night</code></td></tr><tr><td><code>type</code>（舰种）</td><td><code>BB</code> / <code>BC</code> / <code>CA</code> / <code>CL</code> / <code>DD</code> / <code>SS</code> / <code>CV</code> / <code>CVE</code> / <code>TB</code> / <code>DC</code> / <code>HK</code></td></tr><tr><td><code>nation</code></td><td><code>0</code>（盟军）/ <code>1</code>（轴心）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这些值不能翻译</p><p>框架和游戏用这些字符串做匹配。写中文会导致识别失败。</p><p>详见 <a href="/AtlanticFleetSite/docs/features/i18n">多语言与界面文本</a>。</p></div><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>参数系统原理 → <a href="/AtlanticFleetSite/docs/features/params">参数系统</a></li><li>各项详解 → <a href="/AtlanticFleetSite/docs/features/combat">战斗数值</a> / <a href="/AtlanticFleetSite/docs/features/economy">经济与威望</a> / …</li><li>完整 mod.json 结构 → <a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a></li></ul>',35)])])}const g=d(r,[["render",h]]);export{u as __pageData,g as default};
